from pyomo.environ import *

class ChildrenOptimization:
    def __init__(self):
        # Initialize the model
        self.model = ConcreteModel()

        # Sets
        self.model.C = Set(initialize=['Harry', 'Hermione', 'Ron', 'Fred', 'George', 'Ginny'])

        # Parameters
        self.model.Cost = Param(self.model.C, initialize={
            'Harry': 1200,
            'Hermione': 1650,
            'Ron': 750,
            'Fred': 800,
            'George': 800,
            'Ginny': 1500
        })

        # Variables
        self.model.x = Var(self.model.C, domain=Binary)

        # Objective
        def objective_rule(model):
            return sum(model.Cost[child] * model.x[child] for child in model.C)
        self.model.Objective = Objective(rule=objective_rule, sense=minimize)

        # Constraints
        def total_children_constraint(model):
            return inequality(3, sum(model.x[child] for child in model.C), 4)
        self.model.TotalChildrenConstraint = Constraint(rule=total_children_constraint)

        # Ginny must be taken
        def ginnys_must_be_taken(model):
            return model.x['Ginny'] == 1
        self.model.GinnyMustBeTaken = Constraint(rule=ginnys_must_be_taken)

        # If Harry is taken, Fred and George cannot be taken
        def no_fred_george_with_harry(model):
            return model.x['Harry'] + model.x['Fred'] <= 1
        self.model.NoFredGeorgeWithHarry1 = Constraint(rule=no_fred_george_with_harry)
        def no_harry_george(model):
            return model.x['Harry'] + model.x['George'] <= 1
        self.model.NoFredGeorgeWithHarry2 = Constraint(rule=no_harry_george)

        # If George is taken, Fred and Hermione must be taken
        def require_fred_and_hermione_with_george(model):
            return model.x['George'] + model.x['Fred'] >= 1
        self.model.RequireFredAndHermioneWithGeorge1 = Constraint(rule=require_fred_and_hermione_with_george)
        def require_fred_and_hermione_with_george_2(model):
            return model.x['George'] + model.x['Hermione'] >= 1
        self.model.RequireFredAndHermioneWithGeorge2 = Constraint(rule=require_fred_and_hermione_with_george_2)

    def solve(self):
        # Solver options
        solver = SolverFactory('glpk')
        results = solver.solve(self.model, tee=False)

        # Print the results
        if results.solver.status == SolverStatus.ok and results.solver.termination_condition == TerminationCondition.optimal:
            print("Objective Value (Min Cost): ${}".format(value(self.model.Objective)))
            print("Selected Children:")
            for child in self.model.C:
                if value(self.model.x[child]) == 1:
                    print(f"- {child}")
        else:
            print("No optimal solution found.")

def main():
    opt_problem = ChildrenOptimization()
    opt_problem.solve()

if __name__ == "__main__":
    main()

