            'Corn': 1500,
            'Wheat': 1200,
            'Soybeans': 1800,
            'Sorghum': 1600
        })

        # Variables
        self.model.x = Var(self.model.Crops, domain=NonNegativeReals)

        # Objective
        def objective_rule(model):
            return sum(model.Profits[crop] * model.x[crop] for crop in model.Crops)

        self.model.TotalProfit = Objective(rule=objective_rule, sense=maximize)

        # Constraints
        def total_area_constraint(model):
            return sum(model.x[crop] for crop in model.Crops) <= model.TotalAcresAvailable

        self.model.TotalAreaConstraint = Constraint(rule=total_area_constraint)

        def corn_wheat_ratio_constraint(model):
            return model.x['Corn'] >= 2 * model.x['Wheat']

        self.model.CornWheatRatioConstraint = Constraint(rule=corn_wheat_ratio_constraint)

        def soybean_sorghum_ratio_constraint(model):
            return model.x['Soybeans'] >= 0.5 * model.x['Sorghum']

        self.model.SoybeanSorghumRatioConstraint = Constraint(rule=soybean_sorghum_ratio_constraint)

        def wheat_sorghum_ratio_constraint(model):
            return model.x['Wheat'] == 3 * model.x['Sorghum']

        self.model.WheatSorghumRatioConstraint = Constraint(rule=wheat_sorghum_ratio_constraint)

    def solve(self):
