class OptimizationModel:
    def __init__(self):
        self.model = ConcreteModel()

        # Sets
        self.model.D = Set(initialize=['A', 'B', 'C', 'D'])

        # Parameters
        self.model.s = Param(self.model.D, initialize={'A': 1000, 'B': 920, 'C': 800, 'D': 700})
        self.model.p = Param(self.model.D, initialize={'A': 20, 'B': 24, 'C': 16, 'D': 28})
        self.model.c = Param(self.model.D, initialize={'A': 900, 'B': 1000, 'C': 1200, 'D': 1600})

        # Variables
        self.model.x = Var(self.model.D, domain=NonNegativeReals)
        self.model.y = Var(self.model.D, domain=Binary)

        # Objective Function
        def obj_rule(model):
            return sum(model.s[i] * model.y[i] + model.p[i] * model.x[i] for i in model.D)
        self.model.obj = Objective(rule=obj_rule, sense=minimize)

        # Constraints
        def production_target_rule(model):
            return sum(model.x[i] for i in model.D) == 2000
        self.model.production_target = Constraint(rule=production_target_rule)

        def capacity_rule(model, i):
            return model.x[i] <= model.c[i] * model.y[i]
        self.model.capacity_constraint = Constraint(self.model.D, rule=capacity_rule)

    def solve(self):
        solver = SolverFactory('glpk')
