import numpy as np

class ProductionOptimization:
    def __init__(self):
        self.model = ConcreteModel()

        # Sets
        self.model.I = RangeSet(1, 3)  # Products
        self.model.J = RangeSet(1, 3)  # Machines

        # Parameters
        T = np.array([[5, 4, 3], [6, 5, 4], [7, 6, 5]])
        self.model.t = Param(self.model.I, self.model.J, initialize=lambda model, i, j: T[i-1, j-1])

        # Variables
        self.model.C = Var(self.model.I, self.model.J, domain=NonNegativeReals)

        # Objective
        self.model.obj = Objective(expr=self.model.C[3, 3], sense=minimize)

        # Constraints
        # Sequential processing within machines
        def sequential_processing_within_machines(model, i, j):
            if j == 1:
                return model.C[i, j] >= model.C[i, j-1] + model.t[i, j]
            elif j > 1:
                return model.C[i, j] >= model.C[i, j-1] + model.t[i, j]
            else:
                return Constraint.Skip

        self.model.sequential_within = Constraint(self.model.I, self.model.J, rule=sequential_processing_within_machines)

        # Sequential processing across products on same machine
        def sequential_processing_across_products(model, i, i_prime, j):
            if i < i_prime:
                return model.C[i_prime, j] >= model.C[i, j]
            else:
                return Constraint.Skip

        self.model.sequential_across = Constraint(self.model.I, self.model.I, self.model.J, rule=sequential_processing_across_products)

    def solve(self):
        solver = SolverFactory('glpk')
        results = solver.solve(self.model, tee=False)

        # Print the optimal solution and objective value
        if (results.solver.status == SolverStatus.ok) and (results.solver.termination_condition == TerminationCondition.optimal):
            print("Objective value (makespan):", self.model.C[3, 3].value)
            print("Completion times:")
            for i in self.model.I:
                for j in self.model.J:
                    print(f'C[{i},{j}] =', self.model.C[i, j].value)
        else:
            print("No optimal solution found.")

def main():
    opt_problem = ProductionOptimization()
    opt_problem.solve()

if __name__ == "__main__":
    main()

