from pyomo.opt import SolverFactory

class GrainPurchaseOptimization:
    def __init__(self):
        self.model = ConcreteModel()
        self._build_model()

    def _build_model(self):
        # Sets
        M = [1, 2, 3]

        # Parameters
        p = {1: 2.85, 2: 3.05, 3: 2.90}
        s = {1: 3.10, 2: 3.25, 3: 2.95}
        cap = 5000
        initial_stock = 1000
        final_stock = 2000
        max_capacity = 4000
        min_spend = 0
        max_spend = 30000

        # Variables
        self.model.x = Var(M, domain=NonNegativeReals)
        self.model.y = Var(M, domain=NonNegativeReals)

        # Objective
        def obj_rule(model):
            return sum(s[m] * model.y[m] - p[m] * model.x[m] for m in M)
        self.model.obj = Objective(rule=obj_rule, sense=maximize)

        # Constraints
        # Capacity constraints
        def capacity_constraint_rule(model, m):
            if m == 1:
                return model.x[m] - model.y[m] <= cap - initial_stock
            else:
                return model.x[m] - model.y[m] + sum(-model.y[k] for k in M if k < m) <= cap
        self.model.capacity_constraints = Constraint(M, rule=capacity_constraint_rule)

        # Stock level path
        def stock_path_initial_rule(model):
            return sum(model.x[m] for m in M) + initial_stock == final_stock
        self.model.stock_path_initial = Constraint(rule=stock_path_initial_rule)

        def stock_path_final_rule(model):
            return sum(-model.y[m] for m in M) + final_stock <= cap
        self.model.stock_path_final = Constraint(rule=stock_path_final_rule)

        # Financial constraints
        def financial_constraint_rule(model, m):
            return (min_spend, p[m] * model.x[m], max_spend)
        self.model.financial_constraints = Constraint(M, rule=financial_constraint_rule)

        # Non-negativity and other practical constraints could be added here if necessary

    def solve(self):
        solver = SolverFactory('glpk')
        result = solver.solve(self.model, tee=False)
        return result

    def print_solution(self):
        print("Objective value (Total Profit):", self.model.obj())
        for m in self.model.x:
            print(f"Month {m}:")
            print(f"  Units Purchased (x_{m}): {self.model.x[m].value:.2f}")
            print(f"  Units Sold (y_{m}): {self.model.y[m].value:.2f}")

def main():
    optimization_problem = GrainPurchaseOptimization()
    optimization_problem.solve()
    optimization_problem.print_solution()

if __name__ == "__main__":
    main()

