        self.model.P_v = Param(self.model.V, within=Any, 
                               initialize={
                                   1: (0, 0), 2: (10, 0), 3: (12, 3), 4: (14, 15),
                                   5: (16, 13), 6: (18, 9), 7: (8, 6), 8: (6, 12)
                               })

