from pyomo.environ import *

class VehicleOptimizationModel:
    def __init__(self):
        self.model = ConcreteModel()

        # Sets
        self.model.V = Set(initialize=['truck', 'van', 'motorcycle', 'electric'])

        # Parameters
        self.model.capacity = Param(self.model.V, initialize={
            'truck': 100,
            'van': 80,
            'motorcycle': 40,
            'electric': 60
        })
        self.model.pollution = Param(self.model.V, initialize={
            'truck': 100,
            'van': 50,
            'motorcycle': 10,
            'electric': 0
        })
        self.model.minimum_truck_trips = Param(initialize=10)
        self.model.total_products = Param(initialize=1800)
        self.model.max_pollution = Param(initialize=2000)

        # Variables
        self.model.x = Var(self.model.V, domain=NonNegativeIntegers)

        # Objective
        def obj_rule(model):
            return sum(model.pollution[v] * model.x[v] for v in model.V)
        self.model.objective = Objective(rule=obj_rule, sense=minimize)

        # Constraints
        def total_products_rule(model):
            return sum(model.capacity[v] * model.x[v] for v in model.V) >= model.total_products
        self.model.total_products_constraint = Constraint(rule=total_products_rule)

        def max_pollution_rule(model):
            return sum(model.pollution[v] * model.x[v] for v in model.V) <= model.max_pollution
        self.model.max_pollution_constraint = Constraint(rule=max_pollution_rule)

        def min_truck_trips_rule(model):
            return model.x['truck'] >= model.minimum_truck_trips
        self.model.min_truck_trips_constraint = Constraint(rule=min_truck_trips_rule)

        def one_of_van_or_electric_rule(model):
            return model.x['van'] + model.x['electric'] <= max(model.x['van'], model.x['electric']) + 1
        self.model.one_of_van_or_electric_constraint = Constraint(rule=one_of_van_or_electric_rule)

    def solve(self):
        solver = SolverFactory('glpk')
        results = solver.solve(self.model, tee=False)
        if (results.solver.status == SolverStatus.ok) and (results.solver.termination_condition == TerminationCondition.optimal):
            self.display_results()
        else:
            print("No optimal solution found.")

    def display_results(self):
        print("Optimal Solution:")
        for v in self.model.V:
            print(f"Trips for {v}: {self.model.x[v].value}")
        print(f"Total pollution: {self.model.objective()}")

def main():
    vehicle_model = VehicleOptimizationModel()
    vehicle_model.solve()

if __name__ == "__main__":
    main()

