import numpy as np

class ProductionOptimizationModel:
    def __init__(self):
        self.model = ConcreteModel()

        # Sets
        self.model.I = Set(initialize=[1, 2, 3])
        self.model.J = Set(initialize=[1, 2, 3, 4])

        # Parameters
        p = {1: 124, 2: 109, 3: 115}
        c = {1: 73.30, 2: 52.90, 3: 65.40}
        a = {1: 150000, 2: 150000, 3: 100000}
        q = {1: 500, 2: 450, 3: 550}
        b = {1: 20, 2: 20, 3: 16}
        h = {1: 3.5, 2: 4.0, 3: 3.0}
        r_matrix = np.array([
            [5300, 1200, 7400, 5300],
            [4500, 5400, 6500, 7200],
            [4400, 6700, 12500, 13200]
        ])
        D = {1: 23, 2: 20, 3: 23, 4: 22}

        r = {(i+1, j+1): r_matrix[i, j] for i in range(3) for j in range(4)}

        self.model.p = Param(self.model.I, initialize=p)
        self.model.c = Param(self.model.I, initialize=c)
        self.model.a = Param(self.model.I, initialize=a)
        self.model.q = Param(self.model.I, initialize=q)
        self.model.b = Param(self.model.I, initialize=b)
        self.model.h = Param(self.model.I, initialize=h)
        self.model.r = Param(self.model.I, self.model.J, initialize=r)

        # Variables
        self.model.x = Var(self.model.I, self.model.J, domain=NonNegativeReals)
        self.model.y = Var(self.model.I, self.model.J, domain=Binary)
        self.model.s = Var(self.model.I, self.model.J, domain=NonNegativeReals)

        # Objective
        def obj_rule(model):
            return sum((model.p[i] * model.x[i, j] for i in model.I for j in model.J)) - \
                   (sum(model.c[i] * model.x[i, j] for i in model.I for j in model.J) +
                    sum(model.a[i] * model.y[i, j] for i in model.I for j in model.J) +
                    sum(model.h[i] * model.s[i, j] for i in model.I for j in model.J))

        self.model.obj = Objective(rule=obj_rule, sense=maximize)

        # Constraints
        def production_quota_rule(model, i, j):
            return model.x[i, j] <= model.q[i] * D[j]
        self.model.production_quota = Constraint(self.model.I, self.model.J, rule=production_quota_rule)

        def min_batch_rule(model, i, j):
            return model.x[i, j] >= model.b[i] * model.y[i, j]
        self.model.min_batch = Constraint(self.model.I, self.model.J, rule=min_batch_rule)

        def inventory_balance_rule(model, i, j):
            if j > 1:
                return model.s[i, j] == model.s[i, j-1] + model.x[i, j] - model.model.r[i, j]
            else:
                return Constraint.Skip
        self.model.inventory_balance = Constraint(self.model.I, self.model.J, rule=inventory_balance_rule)

        def storage_capacity_rule(model, j):
            return sum(model.s[i, j] for i in model.I) <= 800
        self.model.storage_capacity = Constraint(self.model.J, rule=storage_capacity_rule)

    def solve(self):
        solver = SolverFactory('glpk')
        results = solver.solve(self.model, tee=False)
        return results

    def display_solution(self):
        print("Objective value (Total Profit):", self.model.obj())
        for i in self.model.I:
            for j in self.model.J:
                print(f"Production of product {i} in month {j}: ", self.model.x[i, j].value)
                print(f"Activation status for product {i} in month {j}: ", self.model.y[i, j].value)
                print(f"Inventory of product {i} at end of month {j}: ", self.model.s[i, j].value)

def main():
    opt_model = ProductionOptimizationModel()
    results = opt_model.solve()
    opt_model.display_solution()

if __name__ == "__main__":
    main()

