class TSPModel:
    def __init__(self):
        self.model = ConcreteModel()

        # Sets
        self.model.N = Set(initialize=[1, 2, 3, 4, 5, 6, 7])

        # Parameters
        distances = {
            (1, 2): 86, (1, 3): 49, (1, 4): 57, (1, 5): 31, (1, 6): 69, (1, 7): 50,
            (2, 1): 86, (2, 3): 68, (2, 4): 79, (2, 5): 93, (2, 6): 24, (2, 7): 5,
            (3, 1): 49, (3, 2): 68, (3, 4): 16, (3, 5): 7, (3, 6): 72, (3, 7): 67,
            (4, 1): 57, (4, 2): 79, (4, 3): 16, (4, 5): 90, (4, 6): 69, (4, 7): 1,
            (5, 1): 31, (5, 2): 93, (5, 3): 7, (5, 4): 90, (5, 6): 86, (5, 7): 59,
            (6, 1): 69, (6, 2): 24, (6, 3): 72, (6, 4): 69, (6, 5): 86, (6, 7): 81,
            (7, 1): 50, (7, 2): 5, (7, 3): 67, (7, 4): 1, (7, 5): 59, (7, 6): 81
        }
        self.model.d = Param(self.model.N, self.model.N, initialize=distances, default=0)

        # Variables
        self.model.x = Var(self.model.N, self.model.N, within=Binary)

        # Objective
        def obj_rule(model):
            return sum(model.d[i, j] * model.x[i, j] for i in model.N for j in model.N if i != j)
        self.model.objective = Objective(rule=obj_rule, sense=minimize)

        # Constraints
        def each_location_entered_once_rule(model, j):
            return sum(model.x[i, j] for i in model.N if i != j) == 1
        self.model.each_location_entered_once = Constraint(self.model.N, rule=each_location_entered_once_rule)

        def each_location_exited_once_rule(model, i):
            return sum(model.x[i, j] for j in model.N if i != j) == 1
        self.model.each_location_exited_once = Constraint(self.model.N, rule=each_location_exited_once_rule)

        # Subtour elimination would usually require more sophisticated constraints or formulations.
        # This basic model does not include them for simplicity.

    def solve(self):
        solver = SolverFactory('glpk')
        results = solver.solve(self.model, tee=False)
        return results

    def display_solution(self):
        print("Objective Value: ", self.model.objective())
        print("Tour:")
        for i in self.model.N:
            for j in self.model.N:
                if i != j and self.model.x[i, j].value == 1:
                    print(f"From {i} to {j}")

