class ProductOptimizationModel:
    def __init__(self):
        self.model = ConcreteModel()

        # Sets
        self.model.Q = Set(initialize=[1, 2, 3, 4], doc='Quarters')
        self.model.P = Set(initialize=['I', 'II', 'III'], doc='Products')

        # Parameters
        self.model.T = Param(self.model.P, initialize={'I': 2, 'II': 4, 'III': 3}, doc='Time required per unit of product')
        self.model.H = Param(self.model.Q, initialize={q: 15000 for q in self.model.Q}, doc='Available hours per quarter')
        self.model.D = Param(self.model.Q, self.model.P, initialize={(1, 'I'): 1000, (1, 'II'): 800, (1, 'III'): 1200,
                                                                      (2, 'I'): 1500, (2, 'II'): 1000, (2, 'III'): 1600,
                                                                      (3, 'I'): 1200, (3, 'II'): 900, (3, 'III'): 1100,
                                                                      (4, 'I'): 900, (4, 'II'): 750, (4, 'III'): 950},
                             doc='Demand per quarter for each product')
        self.model.C_s = Param(initialize=5, doc='Storage cost per unit per quarter')
        self.model.C_h = Param(initialize=5, doc='Holding cost per unit until EOY')
        self.model.C_I = Param(self.model.P, initialize={'I': 20, 'II': 20, 'III': 10}, doc='Compensation cost per undelivered unit')
        self.model.Final_Inv = Param(self.model.P, initialize={'I': 150, 'II': 150, 'III': 150}, doc='Final inventory')

        # Variables
        self.model.x = Var(self.model.Q, self.model.P, domain=NonNegativeReals, doc='Units produced per quarter per product')
        self.model.s = Var(self.model.Q, self.model.P, domain=NonNegativeReals, doc='Units stored per quarter per product')
        self.model.u = Var(self.model.Q, self.model.P, domain=NonNegativeReals, doc='Undelivered units per quarter per product')

        # Objective Function
        def obj_rule(model):
            return sum((model.C_s * model.s[q, p] + model.C_I[p] * model.u[q, p]) for q in model.Q for p in model.P)
        self.model.obj = Objective(rule=obj_rule, sense=minimize)

        # Constraints
        def production_time_constraint(model, q):
            return sum(model.T[p] * model.x[q, p] for p in model.P) <= model.H[q]
        self.model.production_time_constraint = Constraint(self.model.Q, rule=production_time_constraint)

        def demand_satisfaction_constraint(model, q):
            if q == 1:
                prev_q = 0
            else:
                prev_q = q - 1
            return model.s[prev_q, p] + model.x[q, p] - model.s[q, p] == model.D[q, p] + model.u[q, p]
        self.model.demand_satisfaction_constraint = Constraint(self.model.Q, self.model.P, rule=demand_satisfaction_constraint)

        def initial_inventory_constraint(model, p):
            return model.s[0, p] == 0
        self.model.initial_inventory_constraint = Constraint(self.model.P, rule=initial_inventory_constraint)

        def final_inventory_constraint(model, p):
            return model.s[4, p] == model.Final_Inv[p]
        self.model.final_inventory_constraint = Constraint(self.model.P, rule=final_inventory_constraint)

        def production_halt_constraint(model, p):
            if p == 'I' and 2 in model.Q:
                return model.x[2, p] == 0
            else:
                return Constraint.Skip
        self.model.production_halt_constraint = Constraint(self.model.Q, self.model.P, rule=production_halt_constraint)

    def solve(self):
        solver = SolverFactory('glpk')
        result = solver.solve(self.model, tee=False)
        return result

    def display_results(self):
        print("Objective Value: ", self.model.obj())
        print("Production Levels:")
        for q in self.model.Q:
            for p in self.model.P:
                print(f"x[{q},{p}] = {self.model.x[q, p].value}")
        print("Stored Units:")
        for q in self.model.Q:
            for p in self.model.P:
                print(f"s[{q},{p}] = {self.model.s[q, p].value}")
        print("Undelivered Units:")
        for q in self.model.Q:
            for p in self.model.P:
                print(f"u[{q},{p}] = {self.model.u[q, p].value}")

